        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeObjectSource.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface ObjectSource: handle missing in uniffiClone")
