    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceObjectSource> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceObjectSource>.allocate(capacity: 1)
