/**
 * Blocklisted shape family (stable identifier; apps map it to copy such as
 * "Too common: U shape"). `NShape`, `CShape` and `Digit2` are reserved: those shapes
 * are rotations/mirrors of Z, U and S and report as those.
 */

public enum BlockedShape: Equatable, Hashable {
    
    /**
     * `Line` family.
     */
    case line
    /**
     * `LShape` family.
     */
    case lShape
    /**
     * `UShape` family.
     */
    case uShape
    /**
     * `Square` family.
     */
    case square
    /**
     * `ZShape` family.
     */
    case zShape
    /**
     * `NShape` family.
     */
    case nShape
    /**
     * `CShape` family.
     */
    case cShape
    /**
     * `VShape` family.
     */
    case vShape
    /**
     * `MShape` family.
     */
    case mShape
    /**
     * `WShape` family.
     */
    case wShape
    /**
     * `SShape` family.
     */
    case sShape
    /**
     * `Digit2` family.
     */
    case digit2
    /**
     * `Digit7` family.
     */
    case digit7
    /**
     * `JShape` family.
     */
    case jShape
    /**
     * `GShape` family.
     */
    case gShape
    /**
     * `Spiral` family.
     */
    case spiral
    /**
     * `Snake` family.
     */
    case snake
    /**
     * `Cross` family.
     */
    case cross
    /**
     * `Plus` family.
     */
    case plus
    /**
     * `TShape` family.
     */
    case tShape
    /**
     * `Equals` family.
     */
    case equals
    /**
     * `Bars` family.
     */
    case bars





}

#if compiler(>=6)
extension BlockedShape: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBlockedShape: FfiConverterRustBuffer {
    typealias SwiftType = BlockedShape

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BlockedShape {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .line
        
        case 2: return .lShape
        
        case 3: return .uShape
        
        case 4: return .square
        
        case 5: return .zShape
        
        case 6: return .nShape
        
        case 7: return .cShape
        
        case 8: return .vShape
        
        case 9: return .mShape
        
        case 10: return .wShape
        
        case 11: return .sShape
        
        case 12: return .digit2
        
        case 13: return .digit7
        
        case 14: return .jShape
        
        case 15: return .gShape
        
        case 16: return .spiral
        
        case 17: return .snake
        
        case 18: return .cross
        
        case 19: return .plus
        
        case 20: return .tShape
        
        case 21: return .equals
        
        case 22: return .bars
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BlockedShape, into buf: inout [UInt8]) {
        switch value {
        
        
        case .line:
